1	package zkcircuit
2	
3	import (
4		"sort"
5		"strings"
6	)
7	
8	// This file holds the domain operations of the persistent workbench. Every
9	// mutating operation validates its request before touching state, runs under
10	// the shared process lock and either commits one complete new state or
11	// commits nothing.
12	
13	// CreateCircuit creates a draft circuit version identified by Name+Version.
14	//
15	// The name must be non-empty and not only whitespace; Version must be
16	// positive; Constraints must be positive; the input counts must not be
17	// negative. Creating an already-existing version is idempotent when the
18	// description is identical (the stored record is returned unchanged); a
19	// differing description is reported as ErrConflict. Nothing about an
20	// existing version — frozen or not — is ever replaced by Create.
21	func (s *Store) CreateCircuit(c Circuit) (Circuit, error) {
22		if err := validateCircuitKey(c.Name, c.Version); err != nil {
23			return Circuit{}, err
24		}
25		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
26			return Circuit{}, err
27		}
28	
29		var result Circuit
30		err := s.withLock(func() (bool, error) {
31			if existing := findCircuit(s.data.Circuits, c.Name, c.Version); existing != nil {
32				if existing.Description != c.Description {
33					return false, conflictf("circuit %q version %d already exists with a different description", c.Name, c.Version)
34				}
35				result = circuitFromPersist(*existing)
36				return false, nil
37			}
38			record := persistCircuit{
39				Name: c.Name, Version: c.Version,
40				Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
41				Frozen: false, Description: c.Description,
42			}
43			s.data.Circuits = append(s.data.Circuits, record)
44			result = circuitFromPersist(record)
45			return true, nil
46		})
47		return result, err
48	}
49	
50	// UpdateCircuit modifies a draft circuit version. It must target an existing,
51	// unfrozen version explicitly: unknown versions yield ErrNotFound and frozen
52	// versions yield ErrFrozen. On success the counts and description are
53	// replaced as one atomic change; partial updates can never be observed.
54	func (s *Store) UpdateCircuit(c Circuit) (Circuit, error) {
55		if err := validateCircuitKey(c.Name, c.Version); err != nil {
56			return Circuit{}, err
57		}
58		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
59			return Circuit{}, err
60		}
61	
62		var result Circuit
63		err := s.withLock(func() (bool, error) {
64			existing := findCircuit(s.data.Circuits, c.Name, c.Version)
65			if existing == nil {
66				return false, notFoundf("circuit %q version %d does not exist", c.Name, c.Version)
67			}
68			if existing.Frozen {
69				return false, frozenf("circuit %q version %d is frozen and its description cannot be modified", c.Name, c.Version)
70			}
71			existing.Constraints = c.Constraints
72			existing.PublicInputs = c.PublicInputs
73			existing.PrivateInputs = c.PrivateInputs
74			existing.Description = c.Description
75			result = circuitFromPersist(*existing)
76			return true, nil
77		})
78		return result, err
79	}
80	
81	// FreezeCircuit freezes a circuit version. Unknown versions yield
82	// ErrNotFound. Freezing an already-frozen version returns that version
83	// unchanged (idempotent). Once frozen, name, version and the three counts
84	// can never change again.
85	func (s *Store) FreezeCircuit(name string, version int) (Circuit, error) {
86		if err := validateCircuitKey(name, version); err != nil {
87			return Circuit{}, err
88		}
89	
90		var result Circuit
91		err := s.withLock(func() (bool, error) {
92			existing := findCircuit(s.data.Circuits, name, version)
93			if existing == nil {
94				return false, notFoundf("circuit %q version %d does not exist", name, version)
95			}
96			if existing.Frozen {
97				result = circuitFromPersist(*existing)
98				return false, nil
99			}
100			existing.Frozen = true
101			result = circuitFromPersist(*existing)
102			return true, nil
103		})
104		return result, err
105	}
106	
107	// RecordSetup records a trusted setup for one frozen circuit version. The
108	// record belongs exclusively to that name+version. Unknown versions yield
109	// ErrNotFound; non-frozen versions yield ErrNotFrozen. Re-registering a
110	// setup for the same version is idempotent and adds no duplicate record.
111	func (s *Store) RecordSetup(name string, version int) (Setup, error) {
112		if err := validateCircuitKey(name, version); err != nil {
113			return Setup{}, err
114		}
115	
116		var result Setup
117		err := s.withLock(func() (bool, error) {
118			circuit := findCircuit(s.data.Circuits, name, version)
119			if circuit == nil {
120				return false, notFoundf("circuit %q version %d does not exist", name, version)
121			}
122			if !circuit.Frozen {
123				return false, notFrozenf("circuit %q version %d must be frozen before its trusted setup is recorded", name, version)
124			}
125			if existing := findSetup(s.data.Setups, name, version); existing != nil {
126				result = setupFromPersist(*existing)
127				return false, nil
128			}
129			record := persistSetup{Name: name, Version: version}
130			s.data.Setups = append(s.data.Setups, record)
131			result = setupFromPersist(record)
132			return true, nil
133		})
134		return result, err
135	}
136	
137	// SubmitJob accepts and stores a prove job. Only kind "prove" is accepted;
138	// no proving computation runs, the accepted request alone is persisted.
139	//
140	// The job id must be non-empty and not only whitespace, circuit name and
141	// version must be explicit and Attempt must be positive. Failure reasons are
142	// distinguishable: ErrNotFound (version unknown), ErrNotFrozen (version is
143	// still a draft) and ErrSetupMissing (no trusted setup for that version). A
144	// refused submission leaves no job behind.
145	//
146	// Resubmitting the same id with the same request returns the stored job;
147	// the same id with different content yields ErrConflict. A stored job stays
148	// pinned to the version submitted, regardless of circuit versions added
149	// later.
150	func (s *Store) SubmitJob(job Job) (Job, error) {
151		if strings.TrimSpace(job.ID) == "" {
152			return Job{}, invalidf("job id must be non-empty and not only whitespace")
153		}
154		if strings.TrimSpace(job.Circuit) == "" {
155			return Job{}, invalidf("job %q must name a circuit", job.ID)
156		}
157		if job.Version <= 0 {
158			return Job{}, invalidf("job %q must pin a positive circuit version", job.ID)
159		}
160		if job.Attempt <= 0 {
161			return Job{}, invalidf("job %q attempt must be a positive integer", job.ID)
162		}
163		if job.Kind != "prove" {
164			return Job{}, StoreError{Kind: ErrUnsupportedKind.Kind,
165				Detail: "job " + job.ID + " has unsupported kind " + job.Kind + "; only \"prove\" jobs are accepted"}
166		}
167	
168		var result Job
169		err := s.withLock(func() (bool, error) {
170			if existing := findJob(s.data.Jobs, job.ID); existing != nil {
171				if !sameJobRequest(*existing, job) {
172					return false, conflictf("job %q already exists with a different request", job.ID)
173				}
174				result = jobFromPersist(*existing)
175				return false, nil
176			}
177			circuit := findCircuit(s.data.Circuits, job.Circuit, job.Version)
178			if circuit == nil {
179				return false, notFoundf("job %q references unknown circuit %q version %d", job.ID, job.Circuit, job.Version)
180			}
181			if !circuit.Frozen {
182				return false, notFrozenf("job %q references circuit %q version %d which is not frozen", job.ID, job.Circuit, job.Version)
183			}
184			if findSetup(s.data.Setups, job.Circuit, job.Version) == nil {
185				return false, setupMissingf("job %q references frozen circuit %q version %d which has no recorded trusted setup",
186					job.ID, job.Circuit, job.Version)
187			}
188			record := persistJob{
189				ID: job.ID, Circuit: job.Circuit, Version: job.Version,
190				Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
191			}
192			s.data.Jobs = append(s.data.Jobs, record)
193			result = jobFromPersist(record)
194			return true, nil
195		})
196		return result, err
197	}
198	
199	// GetCircuit returns one circuit version, sorted-field populated exactly as
200	// stored. Unknown versions yield ErrNotFound.
201	func (s *Store) GetCircuit(name string, version int) (Circuit, error) {
202		if err := validateCircuitKey(name, version); err != nil {
203			return Circuit{}, err
204		}
205		var result Circuit
206		err := s.withLockRead(func() error {
207			existing := findCircuit(s.data.Circuits, name, version)
208			if existing == nil {
209				return notFoundf("circuit %q version %d does not exist", name, version)
210			}
211			result = circuitFromPersist(*existing)
212			return nil
213		})
214		return result, err
215	}
216	
217	// ListCircuits returns all stored circuit versions ordered by circuit name
218	// (lexicographically) and then by ascending version number.
219	func (s *Store) ListCircuits() ([]Circuit, error) {
220		var result []Circuit
221		err := s.withLockRead(func() error {
222			ordered := append([]persistCircuit(nil), s.data.Circuits...)
223			sort.Slice(ordered, func(i, j int) bool {
224				if ordered[i].Name != ordered[j].Name {
225					return ordered[i].Name < ordered[j].Name
226				}
227				return ordered[i].Version < ordered[j].Version
228			})
229			result = make([]Circuit, len(ordered))
230			for i, c := range ordered {
231				result[i] = circuitFromPersist(c)
232			}
233			return nil
234		})
235		return result, err
236	}
237	
238	// GetSetup reports whether a trusted setup is registered for the named
239	// frozen version. A missing record yields ErrNotFound.
240	func (s *Store) GetSetup(name string, version int) (Setup, bool, error) {
241		if err := validateCircuitKey(name, version); err != nil {
242			return Setup{}, false, err
243		}
244		var result Setup
245		found := false
246		err := s.withLockRead(func() error {
247			existing := findSetup(s.data.Setups, name, version)
248			if existing == nil {
249				return nil
250			}
251			result = setupFromPersist(*existing)
252			found = true
253			return nil
254		})
255		return result, found, err
256	}
257	
258	// GetJob returns one stored job by id. Unknown ids yield ErrNotFound.
259	func (s *Store) GetJob(id string) (Job, error) {
260		if strings.TrimSpace(id) == "" {
261			return Job{}, invalidf("job id must be non-empty and not only whitespace")
262		}
263		var result Job
264		err := s.withLockRead(func() error {
265			existing := findJob(s.data.Jobs, id)
266			if existing == nil {
267				return notFoundf("job %q does not exist", id)
268			}
269			result = jobFromPersist(*existing)
270			return nil
271		})
272		return result, err
273	}
274	
275	// ListJobs returns all accepted jobs ordered by job id lexicographically.
276	func (s *Store) ListJobs() ([]Job, error) {
277		var result []Job
278		err := s.withLockRead(func() error {
279			ordered := append([]persistJob(nil), s.data.Jobs...)
280			sort.Slice(ordered, func(i, j int) bool { return ordered[i].ID < ordered[j].ID })
281			result = make([]Job, len(ordered))
282			for i, j := range ordered {
283				result[i] = jobFromPersist(j)
284			}
285			return nil
286		})
287		return result, err
288	}
289	
290	// --- validation helpers ---------------------------------------------------
291	
292	func validateCircuitKey(name string, version int) error {
293		if strings.TrimSpace(name) == "" {
294			return invalidf("circuit name must be non-empty and not only whitespace")
295		}
296		if version <= 0 {
297			return invalidf("circuit %q version must be a positive integer, got %d", name, version)
298		}
299		return nil
300	}
301	
302	func validateCounts(constraints, publicInputs, privateInputs int) error {
303		if constraints <= 0 {
304			return invalidf("constraints must be greater than zero, got %d", constraints)
305		}
306		if publicInputs < 0 {
307			return invalidf("public input count must not be negative, got %d", publicInputs)
308		}
309		if privateInputs < 0 {
310			return invalidf("private input count must not be negative, got %d", privateInputs)
311		}
312		return nil
313	}
314	
315	// --- lookup / mapping helpers --------------------------------------------
316	
317	func findCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
318		for i := range cs {
319			if cs[i].Name == name && cs[i].Version == version {
320				return &cs[i]
321			}
322		}
323		return nil
324	}
325	
326	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
327		for i := range ps {
328			if ps[i].Name == name && ps[i].Version == version {
329				return &ps[i]
330			}
331		}
332		return nil
333	}
334	
335	func findJob(js []persistJob, id string) *persistJob {
336		for i := range js {
337			if js[i].ID == id {
338				return &js[i]
339			}
340		}
341		return nil
342	}
343	
344	func sameJobRequest(stored persistJob, request Job) bool {
345		return stored.Circuit == request.Circuit &&
346			stored.Version == request.Version &&
347			stored.Kind == request.Kind &&
348			stored.Attempt == request.Attempt
349	}
350	
351	func circuitFromPersist(c persistCircuit) Circuit {
352		return Circuit{
353			Name: c.Name, Version: c.Version,
354			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
355			Frozen: c.Frozen, Description: c.Description,
356		}
357	}
358	
359	func setupFromPersist(p persistSetup) Setup {
360		return Setup{Name: p.Name, Version: p.Version}
361	}
362	
363	func jobFromPersist(j persistJob) Job {
364		return Job{
365			ID: j.ID, Circuit: j.Circuit, Version: j.Version,
366			Kind: j.Kind, Attempt: j.Attempt, Artifact: j.Artifact,
367		}
368	}
