1	package main
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7	
8		"github.com/asdhoaiqqq/zkcircuit-workbench/zkcircuit"
9	)
10	
11	// Process exit codes for the data commands.
12	const (
13		exitOK    = 0
14		exitRule  = 1 // business rule failure (not found, conflict, frozen, …)
15		exitUsage = 2 // bad command line
16		exitData  = 3 // storage cannot be read safely (corrupt/truncated/bad format)
17	)
18	
19	// dataCommands is the set of commands backed by a persistent data directory.
20	var dataCommands = map[string]bool{
21		"circuit-create": true,
22		"circuit-update": true,
23		"circuit-freeze": true,
24		"circuit-get":    true,
25		"circuit-list":   true,
26		"setup-record":   true,
27		"setup-get":      true,
28		"job-submit":     true,
29		"job-get":        true,
30		"job-list":       true,
31	}
32	
33	// dispatchDataCommand runs cmd with args. handled is false when cmd is not a
34	// data command, so the caller keeps the historical "unknown command" path.
35	func dispatchDataCommand(cmd string, args []string) (code int, handled bool) {
36		if !dataCommands[cmd] {
37			return exitUsage, false
38		}
39		return runDataCommand(cmd, args), true
40	}
41	
42	func runDataCommand(cmd string, args []string) int {
43		fs, f := newFlagSet(cmd, os.Stderr)
44		if err := fs.Parse(args); err != nil {
45			return exitUsage
46		}
47		if len(fs.Args()) > 0 {
48			fmt.Fprintf(os.Stderr, "error: %s does not accept positional arguments (got %q)\n", cmd, fs.Args()[0])
49			return exitUsage
50		}
51		if f.dir == "" {
52			fmt.Fprintf(os.Stderr, "error: --dir is required for %s\n", cmd)
53			return exitUsage
54		}
55	
56		switch cmd {
57		case "circuit-create":
58			return cmdCircuitCreate(f)
59		case "circuit-update":
60			return cmdCircuitUpdate(f)
61		case "circuit-freeze":
62			return cmdCircuitFreeze(f)
63		case "circuit-get":
64			return cmdCircuitGet(f)
65		case "circuit-list":
66			return cmdCircuitList(f)
67		case "setup-record":
68			return cmdSetupRecord(f)
69		case "setup-get":
70			return cmdSetupGet(f)
71		case "job-submit":
72			return cmdJobSubmit(f)
73		case "job-get":
74			return cmdJobGet(f)
75		case "job-list":
76			return cmdJobList(f)
77		}
78		return exitUsage
79	}
80	
81	func requireNameVersion(cmd string, f *cliFlags) (bool, int) {
82		if f.name == "" {
83			fmt.Fprintf(os.Stderr, "error: --name is required for %s\n", cmd)
84			return false, exitUsage
85		}
86		if f.version <= 0 {
87			fmt.Fprintf(os.Stderr, "error: --version must be a positive integer for %s\n", cmd)
88			return false, exitUsage
89		}
90		return true, exitOK
91	}
92	
93	func openStore(f *cliFlags) (*zkcircuit.Store, int) {
94		store, err := zkcircuit.Open(f.dir)
95		if err != nil {
96			return nil, reportStoreError(err)
97		}
98		return store, exitOK
99	}
100	
101	// reportStoreError prints a failed storage/domain call and returns the exit
102	// code. Rule failures are 1; unreadable data is 3.
103	func reportStoreError(err error) int {
104		if errors.Is(err, zkcircuit.ErrDataCorrupt) {
105			fmt.Fprintf(os.Stderr, "error: read failed: %v\n", err)
106			return exitData
107		}
108		var domainErr zkcircuit.StoreError
109		if errors.As(err, &domainErr) {
110			fmt.Fprintf(os.Stderr, "error: %v\n", err)
111			return exitRule
112		}
113		fmt.Fprintf(os.Stderr, "error: storage failure: %v\n", err)
114		return exitData
115	}
116	
117	func circuitFromFlags(f *cliFlags) zkcircuit.Circuit {
118		return zkcircuit.Circuit{
119			Name: f.name, Version: f.version,
120			Constraints: f.constraints, PublicInputs: f.publicIn, PrivateInputs: f.privateIn,
121			Description: f.description,
122		}
123	}
124	
125	func formatCircuit(c zkcircuit.Circuit) string {
126		return fmt.Sprintf("name=%s version=%d constraints=%d public_inputs=%d private_inputs=%d frozen=%t description=%q",
127			c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Frozen, c.Description)
128	}
129	
130	func formatJob(j zkcircuit.Job) string {
131		s := fmt.Sprintf("id=%s circuit=%s version=%d kind=%s attempt=%d", j.ID, j.Circuit, j.Version, j.Kind, j.Attempt)
132		if j.Artifact != "" {
133			s += " artifact=" + fmt.Sprintf("%q", j.Artifact)
134		}
135		return s
136	}
137	
138	func cmdCircuitCreate(f *cliFlags) int {
139		if ok, code := requireNameVersion("circuit-create", f); !ok {
140			return code
141		}
142		store, code := openStore(f)
143		if store == nil {
144			return code
145		}
