29			t.Fatal(err)
30		}
31		defer s1.Close()
32		defer s2.Close()
33	
34		const n = 60
35		var wg sync.WaitGroup
36		errs := make(chan error, 2*n)
37		for i := 0; i < n; i++ {
38			wg.Add(2)
39			go func(i int) {
40				defer wg.Done()
41				_, e := s1.CreateCircuit(Circuit{Name: fmt.Sprintf("a%03d", i), Version: 1, Constraints: 1, Description: "x"})
42				errs <- e
43			}(i)
44			go func(i int) {
45				defer wg.Done()
46				_, e := s2.CreateCircuit(Circuit{Name: fmt.Sprintf("b%03d", i), Version: 1, Constraints: 1, Description: "x"})
47				errs <- e
48			}(i)
49		}
50		wg.Wait()
51		close(errs)
52		for e := range errs {
53			if e != nil {
54				t.Fatalf("concurrent create: %v", e)
55			}
56		}
57	
58		s3, err := Open(dir)
59		if err != nil {
60			t.Fatalf("reopen: %v", err)
61		}
62		defer s3.Close()
