72	// The draft/freeze race can only end in one of two complete states:
73	//  1. a complete updated description was committed and then frozen, or
74	//  2. the freeze landed first and every later update was rejected.
75	//
76	// A half-updated record must never appear, and the on-disk state after
77	// reopen must equal the final in-memory state.
78	func TestFreezeUpdateRaceNoPartialState(t *testing.T) {
79		for iter := 0; iter < 25; iter++ {
80			dir := t.TempDir()
81			s, err := Open(dir)
82			if err != nil {
83				t.Fatal(err)
84			}
85			if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1, Description: "desc-1"}); err != nil {
86				t.Fatal(err)
87			}
88	
89			var wg sync.WaitGroup
90			start := make(chan struct{})
91			wg.Add(2)
92			go func() {
93				defer wg.Done()
94				<-start
95				for i := 2; i <= 200; i++ {
96					_, err := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: i, Description: fmt.Sprintf("desc-%d", i)})
97					if err != nil {
98						if !errors.Is(err, ErrFrozen) {
99							t.Errorf("unexpected update error: %v", err)
100						}
101						return
102					}
103				}
104			}()
105			go func() {
106				defer wg.Done()
107				<-start
108				s.FreezeCircuit("c", 1)
109			}()
110			close(start)
111			wg.Wait()
112	
113			got, err := s.GetCircuit("c", 1)
114			if err != nil {
115				t.Fatal(err)
116			}
117			if !got.Frozen {
118				t.Fatalf("iter %d: version not frozen after race", iter)
119			}
120			wantDesc := fmt.Sprintf("desc-%d", got.Constraints)
121			if got.Description != wantDesc {
122				t.Fatalf("iter %d: partial update visible: constraints=%d description=%q (want %q)",
123					iter, got.Constraints, got.Description, wantDesc)
124			}
125			if _, err := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: 777, Description: "hax"}); !errors.Is(err, ErrFrozen) {
126				t.Fatalf("post-freeze update: %v", err)
127			}
128			if err := s.Close(); err != nil {
129				t.Fatal(err)
130			}
131	
132			s2, err := Open(dir)
133			if err != nil {
134				t.Fatalf("iter %d: reopen: %v", iter, err)
135			}
136			disk, err := s2.GetCircuit("c", 1)
137			s2.Close()
138			if err != nil || disk != got {
139				t.Fatalf("iter %d: disk state %+v != memory state %+v (err=%v)", iter, disk, got, err)
140			}
141		}
142	}
143	
144	// Concurrent submission of identical create requests must never conflict or
145	// duplicate.
146	func TestConcurrentIdempotentCreate(t *testing.T) {
147		dir := t.TempDir()
148		s1, _ := Open(dir)
149		s2, _ := Open(dir)
150		defer s1.Close()
151		defer s2.Close()
152	
153		var wg sync.WaitGroup
154		errs := make(chan error, 20)
155		c := Circuit{Name: "same", Version: 1, Constraints: 8, Description: "d"}
156		for i := 0; i < 10; i++ {
157			wg.Add(2)
158			go func() { defer wg.Done(); _, e := s1.CreateCircuit(c); errs <- e }()
159			go func() { defer wg.Done(); _, e := s2.CreateCircuit(c); errs <- e }()
160		}
161		wg.Wait()
162		close(errs)
163		for e := range errs {
164			if e != nil {
165				t.Fatalf("idempotent concurrent create failed: %v", e)
166			}
167		}
168		list, _ := s1.ListCircuits()
169		if len(list) != 1 {
170			t.Fatalf("want exactly 1 record, got %d: %+v", len(list), list)
171		}
172	}
