174	// Concurrent identical job submissions likewise collapse to one job.
175	func TestConcurrentIdempotentSubmit(t *testing.T) {
176		dir := t.TempDir()
177		s1, _ := Open(dir)
178		s2, _ := Open(dir)
179		defer s1.Close()
180		defer s2.Close()
181		readyCircuit(t, s1, "c", 1)
182	
183		var wg sync.WaitGroup
184		errs := make(chan error, 20)
185		job := Job{ID: "j1", Circuit: "c", Version: 1, Kind: "prove", Attempt: 1}
186		for i := 0; i < 10; i++ {
187			wg.Add(2)
188			go func() { defer wg.Done(); _, e := s1.SubmitJob(job); errs <- e }()
189			go func() { defer wg.Done(); _, e := s2.SubmitJob(job); errs <- e }()
190		}
191		wg.Wait()
192		close(errs)
193		for e := range errs {
194			if e != nil {
195				t.Fatalf("idempotent concurrent submit failed: %v", e)
196			}
197		}
198		jobs, _ := s1.ListJobs()
199		if len(jobs) != 1 || jobs[0] != job {
200			t.Fatalf("want exactly one pinned job, got %+v", jobs)
201		}
202	}
203	
204	// --- cross-process tests via re-exec -------------------------------------
205	
206	// TestMain recognizes ZKCIRCUIT_HELPER=<mode>: instead of running tests the
207	// process performs one scripted workbench session, printing "ACK …" lines
208	// for operations that returned successfully. The parent verifies every ACK
209	// survived after the helpers exit (or are killed).
210	func TestMain(m *testing.M) {
211		switch mode := os.Getenv("ZKCIRCUIT_HELPER"); mode {
212		case "writer":
213			helperWriter()
214		case "crash-writer":
215			helperCrashWriter()
216		case "setup-job-writer":
217			helperSetupJobWriter()
218		default:
219			os.Exit(m.Run())
220		}
221	}
222	
223	func helperOpen(dir string) *Store {
224		s, err := Open(dir)
225		if err != nil {
226			fmt.Fprintf(os.Stderr, "helper open: %v\n", err)
227			os.Exit(10)
228		}
229		return s
230	}
231	
232	func helperWriter() {
233		dir := os.Getenv("ZKCIRCUIT_DIR")
234		prefix := os.Getenv("ZKCIRCUIT_PREFIX")
235		n, _ := strconv.Atoi(os.Getenv("ZKCIRCUIT_N"))
236		s := helperOpen(dir)
237		defer s.Close()
238		out := bufio.NewWriter(os.Stdout)
239		defer out.Flush()
240		for v := 1; v <= n; v++ {
241			if _, err := s.CreateCircuit(Circuit{Name: prefix, Version: v, Constraints: v, Description: prefix}); err != nil {
242				fmt.Fprintf(os.Stderr, "helper create: %v\n", err)
243				out.Flush()
244				os.Exit(11)
245			}
246			if _, err := s.FreezeCircuit(prefix, v); err != nil {
247				fmt.Fprintf(os.Stderr, "helper freeze: %v\n", err)
248				out.Flush()
249				os.Exit(12)
250			}
251			fmt.Fprintf(out, "ACK circuit %s %d\n", prefix, v)
252			out.Flush()
253		}
254	}
255	
256	func helperSetupJobWriter() {
257		dir := os.Getenv("ZKCIRCUIT_DIR")
258		prefix := os.Getenv("ZKCIRCUIT_PREFIX")
259		n, _ := strconv.Atoi(os.Getenv("ZKCIRCUIT_N"))
260		s := helperOpen(dir)
261		defer s.Close()
262		out := bufio.NewWriter(os.Stdout)
263		defer out.Flush()
264		for v := 1; v <= n; v++ {
265			var last error
266			for i := 0; i < 1000; i++ {
267				_, last = s.RecordSetup(prefix, v)
268				if last == nil || (!errors.Is(last, ErrNotFrozen) && !errors.Is(last, ErrNotFound)) {
269					break
270				}
271			}
272			if last != nil {
273				fmt.Fprintf(os.Stderr, "helper setup: %v\n", last)
274				out.Flush()
275				os.Exit(13)
276			}
277			job := Job{ID: fmt.Sprintf("%s-job-%d", prefix, v), Circuit: prefix, Version: v, Kind: "prove", Attempt: 1}
278			stored, err := s.SubmitJob(job)
279			if err != nil {
280				fmt.Fprintf(os.Stderr, "helper submit: %v\n", err)
281				out.Flush()
282				os.Exit(14)
283			}
284			fmt.Fprintf(out, "ACK job %s\n", stored.ID)
285			out.Flush()
286		}
287	}
288	
289	func helperCrashWriter() {
290		dir := os.Getenv("ZKCIRCUIT_DIR")
291		prefix := os.Getenv("ZKCIRCUIT_PREFIX")
292		s := helperOpen(dir)
293		out := bufio.NewWriter(os.Stdout)
294		defer out.Flush()
295		for v := 1; ; v++ {
296			if _, err := s.CreateCircuit(Circuit{Name: prefix, Version: v, Constraints: v, Description: prefix}); err != nil {
297				fmt.Fprintf(os.Stderr, "crash writer create: %v\n", err)
298				return
299			}
300			if _, err := s.FreezeCircuit(prefix, v); err != nil {
301				fmt.Fprintf(os.Stderr, "crash writer freeze: %v\n", err)
302				return
303			}
304			fmt.Fprintf(out, "ACK circuit %s %d\n", prefix, v)
305			out.Flush()
306		}
307	}
308	
309	// safeBuffer is a bytes.Buffer safe for the os/exec writer goroutine and the
310	// test goroutine to touch concurrently.
311	type safeBuffer struct {
312		mu  sync.Mutex
313		buf bytes.Buffer
314	}
