1	package main
2	
3	import (
4		"bytes"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// capture runs fn with os.Stdout/os.Stderr redirected, returning what was
12	// written. The data commands never share these fds with other goroutines in
13	// these tests.
14	func capture(t *testing.T, fn func()) (stdout, stderr string) {
15		t.Helper()
16		origOut, origErr := os.Stdout, os.Stderr
17		rOut, wOut, err := os.Pipe()
18		if err != nil {
19			t.Fatal(err)
20		}
21		rErr, wErr, err := os.Pipe()
22		if err != nil {
23			t.Fatal(err)
24		}
25		os.Stdout, os.Stderr = wOut, wErr
26	
27		var outBuf, errBuf bytes.Buffer
28		doneOut := make(chan struct{})
29		doneErr := make(chan struct{})
30		go func() { defer close(doneOut); outBuf.ReadFrom(rOut) }()
31		go func() { defer close(doneErr); errBuf.ReadFrom(rErr) }()
32	
33		fn()
34	
35		wOut.Close()
36		wErr.Close()
37		os.Stdout, os.Stderr = origOut, origErr
38		<-doneOut
39		<-doneErr
40		rOut.Close()
41		rErr.Close()
42		return outBuf.String(), errBuf.String()
43	}
44	
45	func runCapture(t *testing.T, args ...string) (int, string, string) {
46		t.Helper()
47		code := -999
48		out, errOut := capture(t, func() { code = run(args) })
49		return code, out, errOut
50	}
51	
52	func TestCLIPreservedCommands(t *testing.T) {
53		code, out, _ := runCapture(t, "version")
54		if code != 0 || strings.TrimSpace(out) != "zkcircuit 0.1.0" {
55			t.Fatalf("version: code=%d out=%q", code, out)
56		}
57		for _, helpArg := range []string{"help", "-h", "--help"} {
58			code, out, _ = runCapture(t, helpArg)
59			if code != 0 || strings.TrimSpace(out) != "usage: zkcircuit [demo|version|help]" {
60				t.Fatalf("%s: code=%d out=%q", helpArg, code, out)
61			}
62		}
63		code, out, _ = runCapture(t, "demo")
64		if code != 0 || !strings.Contains(out, "witness cost order:") {
65			t.Fatalf("demo changed: code=%d out=%q", code, out)
66		}
67		code, _, errOut := runCapture(t, "bogus-command")
68		if code != 2 || !strings.Contains(errOut, `unknown command "bogus-command"`) {
69			t.Fatalf("unknown command: code=%d err=%q", code, errOut)
70		}
71	}
72	
73	func TestCLIFullLifecycle(t *testing.T) {
74		dir := filepath.Join(t.TempDir(), "bench")
75	
76		type res struct {
77			code int
78			out  string
79			err  string
80		}
81		call := func(args ...string) res {
82			c, o, e := runCapture(t, args...)
83			return res{c, o, e}
84		}
85	
86		// Missing --dir is a usage error.
87		if r := call("circuit-create", "--name", "c", "--version", "1"); r.code != 2 {
88			t.Fatalf("missing dir: code=%d err=%s", r.code, r.err)
