package zkcircuit

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math/big"
	"sort"
	"strings"
)

// This file implements R1CS-style constraint definitions: their strict JSON
// form, validation against the declared wire layout of a circuit version, a
// canonical form used both for persistence and for artifact hashing, and the
// modular a·b = c evaluation used by input checking.

// maxModulus bounds accepted moduli. The bound keeps every field element and
// wire coefficient representable in an int32, which makes all arithmetic
// exact in int64 (a product of two residues is at most (p-1)^2 < 2^62).
const maxModulus = 2147483647

// Term is one wire reference with its coefficient: coeff * value(wire).
type Term struct {
	Wire  int    `json:"wire"`
	Coeff string `json:"coeff"`
}

// Constraint is one a·b = c equation modulo the definition's field. Each
// slice is a sum of terms; an empty slice is the zero linear combination.
type Constraint struct {
	A []Term `json:"a"`
	B []Term `json:"b"`
	C []Term `json:"c"`
}

// Definition is an importable constraint set. The JSON file carries modulus
// as a decimal string and an ordered constraints array.
type Definition struct {
	Modulus     string       `json:"modulus"`
	Constraints []Constraint `json:"constraints"`
}

// Artifact is the result of compiling one frozen circuit version. It binds
// the version's name, version number, modulus and constraint count to a
// stable SHA-256 hash; the same logical circuit always compiles to the same
// artifact.
type Artifact struct {
	Name        string
	Version     int
	Modulus     int
	Constraints int
	Hash        string
}

// CheckResult is the verdict of testing one input assignment against a
// compiled artifact. Satisfied reports whether every constraint holds;
// FirstFailure is the 1-based index of the first failing constraint, zero
// when the assignment satisfies the circuit.
type CheckResult struct {
	Satisfied    bool
	Hash         string
	FirstFailure int
}

// Witness is one input assignment: values for the declared public and
// private wires, in declaration order. Values are arbitrary-length signed
// decimal strings interpreted modulo the circuit's field.
type Witness struct {
	Public  []string
	Private []string
}

// ---- parsed / canonical in-memory representation -------------------------

// parsedTerm is a validated term whose coefficient has been reduced into
// [0, modulus).
type parsedTerm struct {
	wire  int
	value int64 // coefficient mod modulus
}

// canonicalConstraint groups merged terms by wire.
type canonicalConstraint struct {
	a, b, c []parsedTerm
}

// canonicalDefinition is a fully validated constraint set in its canonical
// form: terms merged per wire, reduced modulo p, zeros removed, wires sorted
// ascending within each linear combination.
type canonicalDefinition struct {
	modulus     int64
	public      int
	private     int
	constraints []canonicalConstraint
}

// maxWire returns the largest wire index referenced anywhere, or 0 for a
// circuit that only uses the constant wire / empty combinations.
func (d *canonicalDefinition) maxWire() int {
	max := 0
	for _, con := range d.constraints {
		for _, t := range con.a {
			if t.wire > max {
				max = t.wire
			}
		}
		for _, t := range con.b {
			if t.wire > max {
				max = t.wire
			}
		}
		for _, t := range con.c {
			if t.wire > max {
				max = t.wire
			}
		}
	}
	return max
}

// ---- strict JSON parsing --------------------------------------------------

// parseDefinitionJSON parses and fully validates a definition document.
//
// Rejected inputs include malformed JSON, trailing data, duplicate/unknown
// fields, missing modulus or constraints, a non-prime or out-of-range
// modulus, malformed coefficients, wire indexes outside
// [0, 1+public+private) and a constraint count that does not equal the
// circuit version's declared count. The wire layout is wire 0 = constant 1,
// followed by the declared public inputs and then the private inputs.
func parseDefinitionJSON(raw []byte, public, private, wantCount int) (*canonicalDefinition, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	// Reject trailing data after the top-level object.
	var doc struct {
		Modulus     string       `json:"modulus"`
		Constraints []Constraint `json:"constraints"`
	}
	if err := dec.Decode(&doc); err != nil {
		return nil, invalidf("constraint definition is not valid JSON: %v", err)
	}
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != nil && err.Error() != "EOF" {
		return nil, invalidf("constraint definition has trailing data after the top-level object: %v", err)
	}

	// json.Decoder.Decode stops at the end of the first JSON value; detect a
	// second value explicitly.
	if dec.More() {
		return nil, invalidf("constraint definition has trailing data after the top-level object")
	}

	if !json.Valid(raw) {
		return nil, invalidf("constraint definition is not valid JSON")
	}
	if err := requireJSONFields(raw, map[string]bool{"modulus": true, "constraints": true}); err != nil {
		return nil, err
	}
	p, err := parseModulus(doc.Modulus)
	if err != nil {
		return nil, err
	}
	if doc.Constraints == nil {
		return nil, invalidf("constraint definition is missing the \"constraints\" array")
	}
	if len(doc.Constraints) != wantCount {
		return nil, invalidf("constraint count mismatch: definition has %d constraints, version declares %d",
			len(doc.Constraints), wantCount)
	}

	parsed := &canonicalDefinition{
		modulus:     p,
		public:      public,
		private:     private,
		constraints: make([]canonicalConstraint, 0, len(doc.Constraints)),
	}
	maxIndex := 1 + public + private - 1
	for i, con := range doc.Constraints {
		canon, err := parseConstraint(con, p, maxIndex)
		if err != nil {
			return nil, fmt.Errorf("constraint #%d: %w", i+1, err)
		}
		parsed.constraints = append(parsed.constraints, canon)
	}
	return parsed, nil
}

// requireJSONFields decodes into a DisallowUnknownFields decoder and checks
// the top-level object carries exactly the wanted fields. It re-parses raw so
// it can report precisely which required field is missing or which field is
// unknown.
func requireJSONFields(raw []byte, wanted map[string]bool) error {
	var top map[string]json.RawMessage
	if err := json.Unmarshal(raw, &top); err != nil {
		return invalidf("constraint definition is not valid JSON: %v", err)
	}
	for field := range top {
		if !wanted[field] {
			return invalidf("constraint definition has unknown field %q", field)
		}
	}
	for field := range wanted {
		if _, ok := top[field]; !ok {
			return invalidf("constraint definition is missing required field %q", field)
		}
	}
	return nil
}

// parseModulus parses a decimal integer in [2, maxModulus] and requires it to
// be prime.
func parseModulus(s string) (int64, error) {
	n, err := parseSignedDecimal(s)
	if err != nil {
		return 0, invalidf("modulus %q is not a decimal integer: %v", s, err)
	}
	if n < 2 {
		return 0, invalidf("modulus %s must be at least 2", s)
	}
	if n > maxModulus {
		return 0, invalidf("modulus %s exceeds the maximum %d", s, maxModulus)
	}
	if !isPrime(n) {
		return 0, invalidf("modulus %s is not prime", s)
	}
	return n, nil
}

// parseConstraint validates one triple and returns its canonical form.
func parseConstraint(con Constraint, p int64, maxIndex int) (canonicalConstraint, error) {
	a, err := parseLinearCombo(con.A, p, maxIndex, "a")
	if err != nil {
		return canonicalConstraint{}, err
	}
	b, err := parseLinearCombo(con.B, p, maxIndex, "b")
	if err != nil {
		return canonicalConstraint{}, err
	}
	c, err := parseLinearCombo(con.C, p, maxIndex, "c")
	if err != nil {
		return canonicalConstraint{}, err
	}
	return canonicalConstraint{a: a, b: b, c: c}, nil
}

func parseLinearCombo(terms []Term, p int64, maxIndex int, side string) ([]parsedTerm, error) {
	merged := make(map[int]int64)
	for j, t := range terms {
		if t.Wire < 0 || t.Wire > maxIndex {
			return nil, invalidf("term %s[%d] references wire %d outside [0,%d]", side, j, t.Wire, maxIndex)
		}
		v, err := parseSignedDecimal(t.Coeff)
		if err != nil {
			return nil, invalidf("term %s[%d] coefficient %q is not a decimal integer: %v", side, j, t.Coeff, err)
		}
		// Reduce into [0,p); sum may temporarily exceed but int64 is ample
		// because each addend is in [0,p) with p <= 2^31-1.
		merged[t.Wire] = modInt64(merged[t.Wire]+modInt64(v, p), p)
	}
	out := make([]parsedTerm, 0, len(merged))
	for wire, value := range merged {
		if value == 0 {
			continue // canonical form drops zero terms
		}
		out = append(out, parsedTerm{wire: wire, value: value})
	}
