}

// parseBigSignedDecimal parses an arbitrary-length signed decimal string
// (grammar only), returning a non-nil big.Int.
func parseBigSignedDecimal(s string) (*big.Int, error) {
	if s == "" {
		return nil, fmt.Errorf("empty string")
	}
	digits := s
	neg := false
	if s[0] == '-' {
		if len(s) == 1 {
			return nil, fmt.Errorf("sign without digits")
		}
		neg = true
		digits = s[1:]
	}
