	for _, a := range []int64{2, 3, 5, 7, 11} {
		if !millerRabinWitness(n, d, s, a) {
			return false
		}
	}
	return true
}

func millerRabinWitness(n, d int64, s int, a int64) bool {
	x := new(big.Int).Exp(big.NewInt(a), big.NewInt(d), big.NewInt(n))
	if x.Int64() == 1 || x.Int64() == n-1 {
		return true
	}
	for r := 1; r < s; r++ {
		x.Mul(x, x)
		x.Mod(x, big.NewInt(n))
		if x.Int64() == n-1 {
			return true
		}
	}
	return false
}

// ---- artifact hashing -----------------------------------------------------

// artifactHash computes the stable SHA-256 of a compiled version. It folds
// in everything the version's correctness depends on: name, version,
// modulus, public/private split and the ordered, canonical constraints.
//
// Consequently only semantically equivalent rewrites hash alike: JSON
// whitespace, term order, duplicate terms that merge, added/removed zero
// terms, and coefficients differing by a multiple of the modulus. Constraint
// order, modulus, name, version and the input partition change the hash.
func artifactHash(name string, version int, d *canonicalDefinition) string {
	h := sha256.New()
	writeLine := func(prefix, value string) {
		fmt.Fprintf(h, "%s=%s\n", prefix, value)
	}
	writeLine("name", name)
	writeLine("version", fmt.Sprintf("%d", version))
	writeLine("modulus", fmt.Sprintf("%d", d.modulus))
	writeLine("public_inputs", fmt.Sprintf("%d", d.public))
	writeLine("private_inputs", fmt.Sprintf("%d", d.private))
	writeLine("constraint_count", fmt.Sprintf("%d", len(d.constraints)))
	for i, con := range d.constraints {
		fmt.Fprintf(h, "constraint=%d\n", i)
		writeCombo(h, "a", con.a)
		writeCombo(h, "b", con.b)
		writeCombo(h, "c", con.c)
	}
	return hex.EncodeToString(h.Sum(nil))
}

func writeCombo(h *bytesHasher, side string, terms []parsedTerm) {
	fmt.Fprintf(h, "%s=%d", side, len(terms))
	for _, t := range terms {
		fmt.Fprintf(h, " %d:%d", t.wire, t.value)
	}
	h.WriteString("\n")
}

// bytesHasher is the interface sha256.digest already satisfies; the alias
// keeps writeCombo readable.
type bytesHasher = interface {
	Write([]byte) (int, error)
	WriteString(string) (int, error)
}

// ---- canonical JSON for persistence --------------------------------------

func (d *canonicalDefinition) toPersist() persistDefinition {
	out := persistDefinition{
		Modulus:     fmt.Sprintf("%d", d.modulus),
		Public:      d.public,
		Private:     d.private,
		Constraints: make([]persistConstraint, 0, len(d.constraints)),
	}
	combo := func(terms []parsedTerm) []persistTerm {
		tt := make([]persistTerm, 0, len(terms))
		for _, t := range terms {
			tt = append(tt, persistTerm{Wire: t.wire, Coeff: fmt.Sprintf("%d", t.value)})
		}
		return tt
	}
	for _, con := range d.constraints {
		out.Constraints = append(out.Constraints, persistConstraint{
			A: combo(con.a), B: combo(con.b), C: combo(con.c),
		})
	}
	return out
}

func definitionFromPersist(p persistDefinition) (*canonicalDefinition, error) {
	raw, err := json.Marshal(Definition{
		Modulus:     p.Modulus,
		Constraints: constraintsFromPersist(p.Constraints),
	})
	if err != nil {
		return nil, err
	}
	return parseDefinitionJSON(raw, p.Public, p.Private, len(p.Constraints))
}

func constraintsFromPersist(cc []persistConstraint) []Constraint {
	out := make([]Constraint, 0, len(cc))
	terms := func(tt []persistTerm) []Term {
		r := make([]Term, 0, len(tt))
		for _, t := range tt {
			r = append(r, Term{Wire: t.Wire, Coeff: t.Coeff})
		}
		return r
	}
	for _, c := range cc {
		out = append(out, Constraint{A: terms(c.A), B: terms(c.B), C: terms(c.C)})
	}
	return out
}

// ---- input checking -------------------------------------------------------

// parseWitness validates the check input JSON. Both arrays must be present,
// their lengths must match the declaration, and each value must be an
// arbitrarily long signed decimal string.
func parseWitness(raw []byte, public, private int) (Witness, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	var doc struct {
		Public  []string `json:"public"`
		Private []string `json:"private"`
	}
	if err := dec.Decode(&doc); err != nil {
		return Witness{}, invalidf("input is not valid JSON: %v", err)
	}
	if dec.More() {
		return Witness{}, invalidf("input has trailing data after the top-level object")
	}
	if err := requireJSONFields(raw, map[string]bool{"public": true, "private": true}); err != nil {
		return Witness{}, fmt.Errorf("%v", strings.Replace(err.Error(), "constraint definition", "input", 1))
	}
	if doc.Public == nil {
		return Witness{}, invalidf("input is missing the \"public\" array")
	}
	if doc.Private == nil {
		return Witness{}, invalidf("input is missing the \"private\" array")
	}
	if len(doc.Public) != public {
		return Witness{}, invalidf("public input length mismatch: got %d values, version declares %d", len(doc.Public), public)
	}
	if len(doc.Private) != private {
		return Witness{}, invalidf("private input length mismatch: got %d values, version declares %d", len(doc.Private), private)
	}
	for i, v := range doc.Public {
		if _, err := parseBigSignedDecimal(v); err != nil {
			return Witness{}, invalidf("public input #%d value %q is not a decimal integer: %v", i+1, v, err)
		}
	}
	for i, v := range doc.Private {
		if _, err := parseBigSignedDecimal(v); err != nil {
			return Witness{}, invalidf("private input #%d value is not a decimal integer: %v", i+1, err)
		}
	}
	return Witness{Public: doc.Public, Private: doc.Private}, nil
}

// evaluate checks every constraint against the witness and returns the
// 1-based index of the first failure, or 0 when all hold.
func (d *canonicalDefinition) evaluate(w Witness) int {
	p := d.modulus
	// Wire layout: 0 = 1, then public inputs, then private inputs.
	values := make([]int64, 1+d.public+d.private)
	values[0] = 1
	bigP := big.NewInt(p)
	reduce := func(s string) int64 {
		n, _ := parseBigSignedDecimal(s)
		n.Mod(n, bigP)
		return n.Int64()
	}
	for i, s := range w.Public {
		values[1+i] = reduce(s)
	}
	for i, s := range w.Private {
		values[1+d.public+i] = reduce(s)
	}
	combo := func(terms []parsedTerm) int64 {
		var sum int64
		for _, t := range terms {
			sum += t.value * values[t.wire]
		}
		return modInt64(sum, p)
	}
	for i, con := range d.constraints {
		av := combo(con.a)
		bv := combo(con.b)
		cv := combo(con.c)
		if modInt64(av*bv, p) != cv {
			return i + 1
		}
	}
	return 0
}

