			result = artifactFromPersist(*existing)
			return false, nil
		}
		parsed, perr := definitionFromPersist(*circuit.Definition)
		if perr != nil {
			return false, corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
		}
