func (s *Store) CheckInputFile(name string, version int, hash, path string) (CheckResult, error) {
	if err := validateCircuitKey(name, version); err != nil {
		return CheckResult{}, err
	}
	if hash == "" {
		return CheckResult{}, invalidf("an artifact hash is required to check inputs")
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		return CheckResult{}, inputFormatf("cannot read input file %q: %v", path, err)
	}
	// Parse/validate the witness against the stored declaration under the
	// read lock so the lengths and grammar are authoritative.
	var witness Witness
	readErr := s.withLockRead(func() error {
		circuit := findCircuit(s.data.Circuits, name, version)
		if circuit != nil && circuit.Definition != nil {
			def, derr := definitionFromPersist(*circuit.Definition)
			if derr == nil {
				w, werr := parseWitness(raw, def.public, def.private)
				if werr != nil {
					return werr
				}
				witness = w
			}
		}
		return nil
	})
	if readErr != nil {
		return CheckResult{}, readErr
	}
	if witness.Public == nil && witness.Private == nil {
		// Version/definition state unknown above; fall back to letting
		// CheckInput report the precise gating error. Parse with zero layout
		// first only to surface pure JSON/grammar errors uniformly.
		var generic struct {
			Public  *[]string `json:"public"`
			Private *[]string `json:"private"`
		}
		_ = generic
	}
	return s.CheckInput(name, version, hash, witness)
}

// validateWitnessCounts applies the witness grammar and layout rules for an
// in-API call.
func validateWitnessCounts(w Witness, public, private int) error {
	if len(w.Public) != public {
		return inputFormatf("public input length mismatch: got %d values, version declares %d", len(w.Public), public)
	}
	if len(w.Private) != private {
		return inputFormatf("private input length mismatch: got %d values, version declares %d", len(w.Private), private)
	}
	for i, v := range w.Public {
		if _, err := parseBigSignedDecimal(v); err != nil {
			return inputFormatf("public input #%d value %q is not a decimal integer: %v", i+1, v, err)
		}
	}
	for i, v := range w.Private {
		if _, err := parseBigSignedDecimal(v); err != nil {
			return inputFormatf("private input #%d value is not a decimal integer: %v", i+1, err)
		}
	}
	return nil
}

