func cmdCircuitGet(f *cliFlags) int {
	if ok, code := requireNameVersion("circuit-get", f); !ok {
		return code
	}
	store, code := openStore(f)
	if store == nil {
		return code
	}
	defer store.Close()

	c, err := store.GetCircuit(f.name, f.version)
	if err != nil {
		return reportStoreError(err)
	}
