func TestParseWitness(t *testing.T) {
	cases := []struct {
		name string
		doc  string
		ok   bool
	}{
		{"good", `{"public":["1","-2"],"private":["999999999999999999999999"]}`, true},
		{"empty arrays", `{"public":[],"private":[]}`, true},
		{"missing public", `{"private":[]}`, false},
		{"missing private", `{"public":[]}`, false},
		{"unknown field", `{"public":[],"private":[],"x":1}`, false},
		{"null public", `{"public":null,"private":[]}`, false},
		{"public not array", `{"public":1,"private":[]}`, false},
		{"value number", `{"public":[1],"private":[]}`, false},
