func TestDefinitionCountMismatch(t *testing.T) {
	// Document has 1 constraint, version declares 3.
	if _, err := parseDefinitionJSON([]byte(validDef), 1, 1, 3); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("count mismatch: %v", err)
